import{t as e}from"./utils-COoNfFoj.js";var t={slug:`leah-agar`,influencerName:`Leah Agar`,influencerHandle:`@LeahAgar`,influencerAvatarUrl:`${e}/leah-agar-avatar.png`,heroDescription:`I wanted to build this tool to eliminate the time-consuming, tedious process of repurposing blog posts into LinkedIn content—something I’ve long wished I could outsource. It also solves a pain point I know many other B2B social media managers deal with.`,assetTitle:`Leah's Repurposing Tool`,screenshotUrl:`${e}/leah-agar.png`,remixUrl:`https://leahs-repurposing-tool.pplx.app/#/`,promptTitle:`Try Leah's Post`,promptText:`Create a replica of my client’s blog landing page. For each blog post displayed, generate a corresponding LinkedIn-ready document post that aligns with the client’s branding, tone, and style. Each LinkedIn post should be repurposed from its source article and fully ready for publishing. Automatically update and generate new LinkedIn posts every three days based on newly published blog content and add a reminder to the top of my notes app to-do list to review and schedule them for posting when new ones are ready.`};export{t as default};
